SELECT i.item_id AS itemId, i.item_name AS itemName, i.item_brand AS itemBrand, i.item_price AS itemPrice, i.item_category AS itemCategory, i.item_type AS itemType, ii.item_url AS itemUrl FROM item i LEFT JOIN item_img ii ON i.item_id = ii.item_id WHERE 1=1
AND i.item_type IN
#{t}
AND i.item_type = #{type}
AND (ii.is_main = 'Y' OR ii.is_main IS NULL)
ORDER BY i.item_price DESC ORDER BY i.item_price ASC ORDER BY i.item_id DESC
